import React, { useState, useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const DEFAULT_AVATAR = '/default-avatar.png';
const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000';

function getFallbackAvatar(user) {
  if (user?.robloxUserId) {
    return `https://www.roblox.com/headshot-thumbnail/image?userId=${user.robloxUserId}&width=420&height=420&format=png`;
  }
  return DEFAULT_AVATAR;
}

const Header = ({ balance, notifications }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [showWalletModal, setShowWalletModal] = useState(false);
  const [inventory, setInventory] = useState([]);
  const [invLoading, setInvLoading] = useState(false);
  const effectiveBalance = balance != null ? balance : user?.balance;

  const getPageTitle = () => {
    switch(location.pathname) {
      case '/coinflip':
        return 'Coinflip';
      case '/blackjack':
        return 'Blackjack';
      case '/leaderboard':
        return 'Leaderboard';
      case '/stats':
        return 'Statistics';
      case '/provably-fair':
        return 'Provably Fair';
      case '/profile':
        return 'Profile';
      case '/admin':
        return 'Admin Panel';
      default:
        return 'Dashboard';
    }
  };

  const fetchInventory = async () => {
    if (!user) return;
    setInvLoading(true);
    try {
      const identifier = user.id || user.robloxUsername;
      const res = await fetch(`${API_BASE}/api/users/inventory/${identifier}`, {
        headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` }
      });
      if (res.ok) {
        const data = await res.json();
        setInventory(data.items || data.inventory?.items || []);
      }
    } catch (e) {
      console.error('Header wallet inventory fetch failed:', e.message);
    } finally {
      setInvLoading(false);
    }
  };

  useEffect(() => {
    if (showWalletModal) fetchInventory();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showWalletModal]);

  // Keep inventory loaded so the top AMP number shows your total value
  // (AMP balance + inventory worth)
  useEffect(() => {
    if (user) fetchInventory();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  const handleWalletClick = () => {
    setShowWalletModal(true);
  };

  const handleProfileClick = () => {
    navigate('/profile');
  };

  const totalInventoryValue = inventory.reduce(
    (sum, item) => sum + ((item.value || item.details?.value || 0) * (item.quantity || 1)),
    0
  );
  const totalValue = (Number(effectiveBalance) || 0) + totalInventoryValue;

  const displayName = user?.robloxDisplayName || user?.displayName || user?.robloxUsername || 'Anonymous';
  const avatarSrc = user?.avatar || getFallbackAvatar(user);

  return (
    <header className="header">
      <div className="header-left">
        <h2>{getPageTitle()}</h2>
      </div>

      <div className="header-right">
        <div
          className="balance-display"
          title={`Balance: ${Number(effectiveBalance || 0).toLocaleString()} AMP + Inventory: ${totalInventoryValue.toLocaleString()} AMP`}
        >
          {totalValue.toLocaleString()} <span className="ampcoin-text">AMP</span>
        </div>

        <button className="wallet-btn btn btn-secondary" onClick={handleWalletClick}>
          Wallet
        </button>

        <span className="username" onClick={handleProfileClick} style={{cursor: 'pointer'}} title={user?.robloxUsername || ''}>
          {displayName}
        </span>

        <img 
          src={avatarSrc || DEFAULT_AVATAR} 
          alt={`${displayName} avatar`} 
          className="user-avatar"
          onClick={handleProfileClick}
          style={{cursor: 'pointer'}}
          onError={(e) => {
            const fb = getFallbackAvatar(user);
            if (e.target.src !== fb) e.target.src = fb;
            else if (e.target.src !== DEFAULT_AVATAR) e.target.src = DEFAULT_AVATAR;
          }}
        />

        <div className="notifications">
          <span className="notification-icon">🔔</span>
          {notifications && notifications.length > 0 && (
            <span className="notification-badge">{notifications.length}</span>
          )}
        </div>
      </div>

      {showWalletModal && (
        <div className="wallet-modal-overlay wallet-modal-overlay-lg" onClick={() => setShowWalletModal(false)}>
          <div className="wallet-modal wallet-modal-lg" onClick={(e) => e.stopPropagation()}>
            <div className="wallet-modal-header">
              <div className="modal-title-section">
                <h2>💼 Wallet & Inventory</h2>
                <p className="modal-balance">
                  Balance: <span className="balance-highlight">{Number(effectiveBalance || 0).toLocaleString()} AMP</span>
                  <span className="modal-balance-sep"> • </span>
                  {inventory.length} item{inventory.length === 1 ? '' : 's'}
                </p>
              </div>
              <button
                className="modal-close-btn"
                onClick={() => setShowWalletModal(false)}
              >
                ×
              </button>
            </div>
            <div className="wallet-modal-content">
              <div className="inventory-section">
                <div className="section-header">
                  <h3>Your Items</h3>
                  <span className="items-count">{inventory.length} items</span>
                </div>
                <div className="inventory-grid wallet-inventory-grid">
                  {invLoading ? (
                    <div className="no-items">Loading inventory...</div>
                  ) : inventory.length > 0 ? (
                    inventory.map((item, idx) => (
                      <div key={item.itemId || item.id || idx} className="inventory-item wallet-inventory-item">
                        <div className="item-image">
                          {item.image || item.imageUrl || item.details?.imageUrl ? (
                            <img
                              src={item.image || item.imageUrl || item.details?.imageUrl}
                              alt={item.name || item.details?.name || 'item'}
                              onError={(e) => { e.target.style.display = 'none'; }}
                            />
                          ) : (
                            <div className="default-item-icon">💎</div>
                          )}
                        </div>
                        <div className="item-details">
                          <h4>{item.name || item.details?.name || item.itemName || 'Unknown'}</h4>
                          <p className="item-value">
                            {((item.value || item.details?.value || 0) * (item.quantity || 1)).toLocaleString()} AMP
                            {(item.quantity || 1) > 1 && <span className="item-qty"> × {item.quantity}</span>}
                          </p>
                          <span className={`badge badge-${item.rarity || item.details?.rarity || 'common'}`}>
                            {item.rarity || item.details?.rarity || 'common'}
                          </span>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="no-items">No items in your inventory</div>
                  )}
                </div>
              </div>
            </div>
            <div className="wallet-modal-footer">
              <div className="wallet-footer-spacer" />
              <div className="wallet-total-box">
                <span className="wallet-total-label">Total inventory value</span>
                <span className="wallet-total-value">{totalInventoryValue.toLocaleString()} AMP</span>
              </div>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Header;
